from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.minute_buffer = {}
        self.last_completed_bar_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.profit_target_pct = 0.50

    def OnData(self, slice: Slice):
        now = self.Time
        algorithm_date = now.date()

        # Immediately liquidate any SPY equity position created by exercise/assignment.
        equity_holding = self.Portfolio[self.spy_symbol]
        if equity_holding.Invested:
            self.Debug(
                f"{now}: Unexpected SPY equity position detected; liquidating assignment/exercise position."
            )
            self.Liquidate(self.spy_symbol, "Unexpected exercise or assignment")
            return

        # Never intentionally hold through expiration.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if algorithm_date >= expiry_date:
                self.Debug(
                    f"{now}: Option expiration processing began for {self.held_option}; liquidating."
                )
                self._liquidate_option("Expiration processing")
                return

            # Time stop on the trading day immediately preceding expiration.
            if algorithm_date == expiry_date - timedelta(days=1):
                if now.time() >= time(15, 45):
                    self._liquidate_option("Expiration-eve time stop")
                    return

        # Evaluate the profit target using the current Slice quote.
        if self.held_option is not None and self.entry_price is not None:
            quote = slice.QuoteBars.get(self.held_option)
            if quote is not None:
                bid = float(quote.Bid.Close)
                ask = float(quote.Ask.Close)

                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    target = self.entry_price * (1.0 + self.profit_target_pct)

                    if midpoint >= target:
                        self._liquidate_option("Profit target")
                        return

        # Build five-minute SPY bars from minute TradeBars.
        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

    def _process_minute_bar(self, bar: TradeBar):
        local_time = bar.Time.time()

        # Regular session only: 09:30 through 16:00 New York time.
        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        session_start = bar.Time.replace(hour=9, minute=30, second=0, microsecond=0)
        elapsed_minutes = int((bar.Time - session_start).total_seconds() // 60)

        if elapsed_minutes < 0:
            return

        bucket_index = elapsed_minutes // 5
        bucket_start = session_start + timedelta(minutes=bucket_index * 5)
        bucket_end = bucket_start + timedelta(minutes=5)

        # Finalize an earlier bucket when a later bucket arrives.
        for key in sorted(list(self.minute_buffer.keys())):
            if key < bucket_start:
                bars = self.minute_buffer.pop(key)
                self._finalize_bucket(key, bars)

        self.minute_buffer.setdefault(bucket_start, {})[bar.Time] = bar

    def _finalize_bucket(self, bucket_start: datetime, bars_by_time: dict):
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        # Missing minute data means no consolidated bar and no MA update.
        if any(t not in bars_by_time for t in expected_times):
            return

        bars = [bars_by_time[t] for t in expected_times]
        close = bars[-1].Close
        bar_end = bucket_start + timedelta(minutes=5)

        self.fast_window.Add(float(close))
        self.slow_window.Add(float(close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        fast_current = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow_current = sum(self.slow_window[i] for i in range(20)) / 20.0

        # Previous completed-bar averages require the prior 6 fast and 21 slow values.
        if self.fast_window.Count < 6 or self.slow_window.Count < 21:
            return

        fast_previous = sum(self.fast_window[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.slow_window[i] for i in range(1, 21)) / 20.0

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        bullish_crossover = (
            fast_previous <= slow_previous
            and fast_current > slow_current
        )

        if bullish_crossover:
            self._attempt_entry(close)

    def _attempt_entry(self, spy_price: float):
        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
        ):
                return

        chains = self.CurrentSlice.OptionChains
        chain = chains.get(self.option.Symbol)

        if chain is None:
            self.Debug(f"{self.Time}: Skipped call selection; no option chain in Slice.")
            return

        current_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug(f"{self.Time}: Skipped call selection; no eligible expiration.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped call selection; no qualifying call at "
                f"{selected_expiry}."
            )
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _liquidate_option(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self.CancelOrder(self.entry_ticket.OrderId, f"Cancel entry before exit: {reason}")

        if self.Portfolio[self.held_option].Quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -self.Portfolio[self.held_option].Quantity,
                tag=reason
            )
            self.Debug(f"{self.Time}: Exit submitted for {self.held_option}: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"{self.Time}: Entered 1 call {self.held_option} "
                        f"at filled price {self.entry_price:.4f}."
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: Exited {order_event.Symbol} at "
                        f"{order_event.FillPrice:.4f}."
                    )
                    self.exit_ticket = None
                    self.entry_ticket = None
                    self.held_option = None
                    self.entry_price = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None
